-- Generated by tools/build_patch18_price_migration.py. No per-restart boost.
USE player;
CREATE TABLE IF NOT EXISTS web_m2p_price_override (
 k VARCHAR(64) PRIMARY KEY,v BIGINT NOT NULL,updated_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS web_m2p_price_migration_old (
 migration VARCHAR(32) NOT NULL,k VARCHAR(64) NOT NULL,v BIGINT NOT NULL,
 source VARCHAR(16) NOT NULL,at DATETIME NOT NULL,PRIMARY KEY(migration,k)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TEMPORARY TABLE pb18_price_seed (k VARCHAR(64) PRIMARY KEY,v BIGINT NOT NULL);
DELIMITER //
CREATE PROCEDURE IF NOT EXISTS pb18_price_migrate_v18()
main: BEGIN
 DECLARE done BIGINT DEFAULT 0;
 DECLARE boost BIGINT DEFAULT 0;
 DECLARE moon BIGINT DEFAULT 0;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 START TRANSACTION;
 SELECT value INTO done FROM web_m2p_contract_state WHERE name='prices_patch18' FOR UPDATE;
 IF done=18 THEN COMMIT; LEAVE main; END IF;
 -- Include all operator overrides, and every legacy default affected by this
 -- migration. The snapshot and marker commit atomically with resulting prices.
 SELECT 'patch18',k,v,'override',NOW() FROM web_m2p_price_override;
 SELECT 'patch18',k,v,'default',NOW() FROM pb18_price_seed;
 SELECT v INTO boost FROM web_m2p_price_migration_old WHERE migration='patch18' AND k='glob:bonus_boost_pct';
 SELECT v INTO moon FROM web_m2p_price_migration_old WHERE migration='patch18' AND k='glob:moonlight_pct';
 SELECT CONCAT('bonusq:',SUBSTRING(k,7)),GREATEST(0,10000+(GREATEST(0,LEAST(65535,100+TRUNCATE((v-100)*(100+boost)/100,0)))-100)*145),NOW()
 FROM web_m2p_price_migration_old WHERE migration='patch18' AND k LIKE 'bonus:%'
 ON DUPLICATE KEY UPDATE v=VALUES(v),updated_at=VALUES(updated_at);
 SELECT CONCAT('intq:',SUBSTRING(k,5)),GREATEST(0,10000+(v-100)*145),NOW()
 FROM web_m2p_price_migration_old WHERE migration='patch18' AND k LIKE 'int:%'
 ON DUPLICATE KEY UPDATE v=VALUES(v),updated_at=VALUES(updated_at);
 SELECT 'mat:50011',ROUND(v*(100+moon)/100*0.65),NOW()
 FROM web_m2p_price_migration_old WHERE migration='patch18' AND k='mat:50011'
 ON DUPLICATE KEY UPDATE v=VALUES(v),updated_at=VALUES(updated_at);
 ON DUPLICATE KEY UPDATE v=VALUES(v),updated_at=VALUES(updated_at);
 UPDATE web_m2p_contract_state SET value=18,updated_at=NOW() WHERE name='prices_patch18';
 COMMIT;
END//
CALL pb18_price_migrate_v18()//
DELIMITER ;
DROP TEMPORARY TABLE pb18_price_seed;
